INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (1,'PKWT (kontrak)','pkwt kontrak perpanjangan waktu tertentu perjanjian','PKWT paling lama 2 tahun, dapat diperpanjang paling banyak 2 kali, masing-masing paling lama 1 tahun; total maksimal 4 tahun (Pasal 82 ayat 2). Rencana perpanjangan wajib diberitahukan tertulis paling lambat 7 hari sebelum berakhir (Pasal 82 ayat 3). PKWT wajib tertulis, bahasa Indonesia, huruf latin; jika tidak, demi hukum menjadi PKWTT (Pasal 83-85). PKWT tidak boleh mensyaratkan masa percobaan; jika ada, batal demi hukum dan masa kerja tetap dihitung (Pasal 86). PKWT hanya untuk pekerjaan sekali selesai, sementara, musiman, produk baru, atau tidak tetap; tidak boleh untuk pekerjaan yang bersifat tetap (Pasal 87 ayat 1-2). PKWT wajib dicatatkan paling lambat 3 hari kerja sejak ditandatangani (Pasal 87 ayat 3). PKWT yang tidak memenuhi syarat demi hukum menjadi PKWTT (Pasal 87 ayat 5-6). Uang kompensasi saat PKWT berakhir sesuai masa kerja, besarannya diatur PP (Pasal 88). Pengakhiran sepihak sebelum waktunya wajib membayar ganti rugi sebesar upah sampai batas waktu PKWT berakhir (Pasal 90).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (2,'PKWTT dan masa percobaan','pkwtt tetap masa percobaan probation karyawan tetap','Masa percobaan PKWTT paling lama 3 bulan (Pasal 92 ayat 1). Selama percobaan, upah minimal 75% dari upah jabatan dan tidak boleh di bawah UMP/UMK; jaminan sosial wajib (Pasal 92 ayat 2). Masa percobaan wajib dicantumkan secara tertulis dalam PKWTT atau surat pengangkatan; jika tidak, dianggap tidak ada (Pasal 92 ayat 3-6). Masa percobaan dihitung sebagai masa kerja. Setelah masa percobaan selesai, pemberi kerja wajib mengangkat menjadi PKWTT (Pasal 92). PKWTT boleh tertulis atau lisan; jika lisan, wajib dibuat surat pengangkatan tertulis (Pasal 93-94).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (3,'Alih daya (outsourcing)','alih daya outsourcing vendor jasa penunjang subkontrak','Alih daya hanya untuk jasa penunjang atau kegiatan yang tidak berhubungan langsung dengan proses produksi. Contoh jasa penunjang: kebersihan, penyediaan makanan, pengamanan, dan angkutan pekerja (Pasal 95). Jika pekerja alih daya dipakai untuk kegiatan yang berhubungan langsung dengan proses produksi, status hubungan kerja demi hukum beralih ke perusahaan pemberi pekerjaan (Pasal 98 ayat 1). Hubungan kerja pekerja alih daya dengan perusahaan alih daya berdasarkan perjanjian tertulis (PKWT atau PKWTT). Syarat kerja, upah, jaminan sosial, dan penyelesaian perselisihan menjadi tanggung jawab perusahaan alih daya (Pasal 99 ayat 1-2). Jika vendor berganti dan objek pekerjaan tetap, hak pekerja dialihkan dan masa kerja pada vendor sebelumnya dihitung kumulatif (Pasal 99 ayat 3-4). Perusahaan alih daya wajib berbentuk PT dan memiliki perizinan berusaha; dilarang memotong atau mengurangi hak normatif pekerja (Pasal 99 ayat 5-7). Perjanjian alih daya yang sudah ada tetap berlaku sampai berakhir; penyesuaian paling lama 1 tahun sejak diundangkan (Pasal 306).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (4,'Waktu kerja dan lembur','jam kerja lembur overtime waktu kerja shift upah lembur','Waktu kerja 7 jam per hari dan 40 jam per minggu untuk 6 hari kerja, atau 8 jam per hari dan 40 jam per minggu untuk 5 hari kerja (Pasal 115 ayat 2). Lembur wajib memenuhi tiga syarat: ada persetujuan pekerja, ada perintah tertulis atau digital, dan batas paling lama 4 jam per hari dan 18 jam per minggu (Pasal 116 ayat 1). Upah lembur 1,5 kali upah sejam untuk jam pertama dan 2 kali untuk jam berikutnya. Upah sejam = (upah pokok + tunjangan tetap) / 173 (Pasal 116 ayat 2-3). Pelanggaran aturan lembur dikenai sanksi administratif (Pasal 117). Pekerja tidak wajib bekerja pada hari libur resmi; jika dipekerjakan, upah lembur mengikuti Pasal 125 ayat 3-4. Lembur yang tidak dibayar adalah tindak pidana (Pasal 285).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (5,'Istirahat dan cuti','cuti tahunan istirahat libur mingguan cuti melahirkan haid menyusui cuti sakit','Istirahat antarjam kerja minimal 30 menit setelah 4 jam kerja terus-menerus (Pasal 118 ayat 2). Libur mingguan 1 hari untuk 6 hari kerja, atau 2 hari untuk 5 hari kerja. Istirahat panjang 30 hari kalender setelah 5 tahun berturut-turut; pekerja yang mengambilnya tidak berhak cuti tahunan pada tahun berjalan (Pasal 118 ayat 4). Cuti tahunan minimal 12 hari kerja setelah 12 bulan bekerja terus-menerus (Pasal 118 ayat 5). Pekerja perempuan yang haid dan merasa sakit tidak wajib bekerja sampai 2 hari (Pasal 120). Cuti melahirkan minimal 3 bulan pertama, dapat diperpanjang 3 bulan jika ada kondisi khusus dengan surat dokter; keguguran berhak istirahat 1,5 bulan atau sesuai surat dokter (Pasal 121). Pekerja perempuan menyusui berhak fasilitas laktasi (Pasal 122). Cuti tahunan, cuti melahirkan, dan istirahat keguguran dibayar penuh; bulan keempat cuti melahirkan dibayar penuh, bulan kelima dan keenam 75% (Pasal 123). Cuti pendampingan istri melahirkan 2 hari, dapat ditambah paling lama 3 hari (Pasal 124).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (6,'Upah minimum (UMP, UMK, sektoral)','upah minimum ump umk umsp umsk gaji minimum kabupaten provinsi','Upah minimum terdiri atas UMP, UMK, UMSP, dan UMSK. Gubernur wajib menetapkan UMP dan UMSP. UMK harus lebih tinggi dari UMP (Pasal 137). Penetapan memperhatikan kebutuhan hidup layak, kondisi ekonomi, dan ketenagakerjaan (Pasal 138). Formula mempertimbangkan pertumbuhan ekonomi, inflasi, dan indeks tertentu; dipakai nilai tertinggi antara formula dan KHL (Pasal 139). UMP/UMK berlaku bagi pekerja dengan masa kerja kurang dari 1 tahun. Upah di bawah UMP/UMK dilarang; perusahaan yang belum mampu dapat mengajukan pengecualian kepada gubernur dengan kesepakatan bipartit dan audit eksternal (Pasal 140). Upah di atas UMP/UMK ditetapkan berdasarkan kesepakatan di perusahaan (Pasal 143). Usaha mikro dan kecil dapat menyepakati upah minimal 50% dari UMP/UMK (Pasal 144). Upah di bawah UMP/UMK adalah tindak pidana (Pasal 288). Angka UMP/UMK tahun berjalan tidak ada di basis ini; cek SK terbaru.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (7,'Struktur dan skala upah, komponen upah','struktur skala upah tunjangan upah pokok komponen gaji','Pengusaha wajib menyusun struktur dan skala upah, dilampirkan dalam PP atau PKB, sebagai pedoman untuk pekerja dengan masa kerja 1 tahun atau lebih (Pasal 146). Upah wajib ditinjau secara berkala (Pasal 148). Jika upah terdiri dari upah pokok dan tunjangan tetap, upah pokok minimal 75% dari jumlah keduanya (Pasal 150). Upah sama untuk pekerjaan yang sama nilainya (Pasal 135 ayat 2). Kesepakatan upah di bawah ketentuan UU batal demi hukum (Pasal 135 ayat 4-5). Keterlambatan pembayaran upah dikenai denda sesuai persentase tertentu (Pasal 135 ayat 6). Pekerja berhak menuntut pembayaran upah tanpa batas waktu (Pasal 152).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (8,'Upah saat tidak masuk kerja dan sakit','upah sakit tidak masuk kerja izin keluarga meninggal menikah sakit gaji dipotong','Upah tidak dibayar jika pekerja tidak bekerja, kecuali: sakit, keluarga meninggal, menikah, istri melahirkan, menjalankan kewajiban negara, ibadah, melaksanakan hak istirahat, tugas serikat yang tercatat, tugas pendidikan dari pemberi kerja, dan mogok sah (Pasal 149 ayat 1-2). Upah sakit: 100% untuk 4 bulan pertama, 75% untuk 4 bulan kedua, 50% untuk 4 bulan ketiga, dan 25% untuk bulan berikutnya sebelum PHK (Pasal 149 ayat 3). Upah tetap dibayar untuk keperluan keluarga: menikah 3 hari; khitan atau pembaptisan anak 2 hari; istri melahirkan atau keguguran 2 hari; keluarga inti meninggal 2 hari; anggota keluarga satu rumah meninggal 1 hari (Pasal 149 ayat 4).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (9,'Pesangon, UPMK, dan UPH','pesangon uang penghargaan masa kerja upmk uph uang penggantian hak severance besaran','Dasar upah pesangon, UPMK: upah pokok dan tunjangan tetap. Upah harian dikali 30; upah satuan hasil memakai rata-rata 12 bulan terakhir; jika di bawah UMP/UMK, dasarnya UMP/UMK (Pasal 234). PESANGON (Pasal 232 ayat 2): masa kerja kurang dari 1 tahun 1 bulan upah; 1 sampai kurang 2 tahun 2 bulan; 2 sampai kurang 3 tahun 3 bulan; 3 sampai kurang 4 tahun 4 bulan; 4 sampai kurang 5 tahun 5 bulan; 5 sampai kurang 6 tahun 6 bulan; 6 sampai kurang 7 tahun 7 bulan; 7 sampai kurang 8 tahun 8 bulan; 8 tahun atau lebih 9 bulan. UPMK (Pasal 232 ayat 3): 3 sampai kurang 6 tahun 2 bulan; 6 sampai kurang 9 tahun 3 bulan; 9 sampai kurang 12 tahun 4 bulan; 12 sampai kurang 15 tahun 5 bulan; 15 sampai kurang 18 tahun 6 bulan; 18 sampai kurang 21 tahun 7 bulan; 21 sampai kurang 24 tahun 8 bulan; 24 tahun atau lebih 10 bulan. UPH (Pasal 232 ayat 4): cuti tahunan yang belum diambil dan belum gugur, ongkos pulang pekerja dan keluarga, serta hak lain sesuai perjanjian, PP, atau PKB. Uang pisah sesuai perjanjian, PP, atau PKB; jika tidak diatur, minimal 1 bulan upah (Pasal 233). Iuran pensiun yang dibayar penuh pemberi kerja boleh diperhitungkan dengan pesangon (Pasal 248). Untuk usaha mikro dan kecil, besaran pesangon, UPMK, UPH, dan uang pisah disepakati (Pasal 250). Pesangon dan hak pekerja yang belum dibayar menjadi utang yang dijamin seluruh aset pemberi kerja (Pasal 299); jika pailit atau dilikuidasi, upah dan hak pekerja didahulukan (Pasal 151).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (10,'Pengali pesangon menurut alasan PHK','pengali faktor pesangon alasan phk merger tutup pailit pensiun meninggal sakit berkepanjangan ditahan mangkir','Merger, pekerja tidak bersedia lanjut: pesangon 1x, UPMK 1x, UPH (Pasal 236 ayat 1). Merger, pemberi kerja tidak mau menerima: pesangon 2x, UPMK 1x, UPH (Pasal 236 ayat 2). Perusahaan tutup karena rugi terus-menerus 2 tahun: pesangon 1x, UPMK 1x, UPH (Pasal 237). Tutup permanen oleh pemilik: pesangon 1x, UPMK 1,5x, UPH (Pasal 238). Keadaan memaksa (kahar): pesangon 1x, UPMK 1x, UPH (Pasal 239). Penundaan pembayaran utang (PKPU) atau pailit: pesangon 1x, UPMK 1x, UPH (Pasal 240). Permohonan PHK oleh pekerja karena perbuatan pemberi kerja: pesangon 2x, UPMK 1x, UPH (Pasal 241 ayat 1). Pelanggaran tidak terbukti, PHK tetap dilakukan: tanpa pesangon dan UPMK; UPH dan uang pisah (Pasal 241 ayat 2). Pengunduran diri: hanya UPH dan uang pisah (Pasal 242). Mangkir 5 hari kerja berturut-turut: dianggap mengundurkan diri, UPH dan uang pisah (Pasal 243). Pelanggaran setelah surat peringatan ketiga (SP3): pesangon 1x, UPMK 1x, UPH (Pasal 244). Sakit berkepanjangan atau cacat akibat kerja melebihi 12 bulan: pesangon 2x, UPMK 2x, UPH 1x (Pasal 246). Pensiun: pesangon 2x, UPMK 1x, UPH (Pasal 247). Pekerja meninggal dunia: ahli waris menerima pesangon 2x, UPMK 1x, UPH (Pasal 249). Pekerja ditahan karena dugaan pidana: upah tidak dibayar, tetapi wajib membantu keluarga 25% sampai 50% upah paling lama 6 bulan (Pasal 245 ayat 1).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (11,'Dana cadangan pesangon','dana cadangan pesangon cadangan dana pensiun','Pengusaha wajib menyediakan dana cadangan pesangon untuk PHK selain pensiun, bagi pekerja yang belum ikut program pensiun (Pasal 253 ayat 1-2). Dana dikelola lembaga pemerintah; usaha mikro dan kecil dikecualikan (Pasal 253 ayat 3-4). Pengusaha yang tidak menyediakan dana cadangan dikenai sanksi administratif, mulai dari peringatan tertulis sampai pencabutan perizinan berusaha (Pasal 253 ayat 6-7). Besaran dan tata cara teknis diatur lebih lanjut dalam peraturan pelaksana.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (12,'Mencegah PHK: tahapan wajib','pencegahan phk cegah phk tahapan efisiensi merumahkan lembur shift kurangi jam','Pemberi kerja, pekerja, serikat, dan pemerintah wajib mencegah PHK dengan segala upaya (Pasal 228 ayat 1). Tahapan pencegahan secara berurutan: (a) kurangi kerja lembur pada hari libur; (b) kurangi kerja lembur harian; (c) kurangi jumlah shift; (d) kurangi jam kerja atau hari kerja; (e) tidak memperpanjang PKWT yang sudah berakhir; (f) tidak mengganti pekerja yang memasuki usia pensiun; (g) sesuaikan upah dan fasilitas manajerial; (h) rumahkan pekerja PKWTT sementara atau bergiliran; (i) tawarkan pensiun dini sukarela; (j) tawarkan pensiun bagi pekerja yang memenuhi syarat (Pasal 228 ayat 2).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (13,'Prosedur PHK dan larangan PHK','phk pemutusan hubungan kerja pecat dipecat bipartit larangan phk batal demi hukum sakit hamil menikah','Jika PHK tidak terhindarkan, wajib dirundingkan secara bipartit dengan serikat atau pekerja (Pasal 228 ayat 3). Perundingan bipartit paling lama 30 hari kerja sejak dimulai (Pasal 228 ayat 4). Jika bipartit gagal, penyelesaian melalui prosedur PHI (Pasal 228 ayat 5). PHK yang tidak disepakati hanya dapat dilakukan setelah ada penetapan PHI yang berkekuatan hukum tetap (Pasal 228 ayat 6). PHK tanpa kesepakatan atau tanpa putusan PHI yang berkekuatan hukum tetap batal demi hukum, dan pekerja wajib dipekerjakan kembali (Pasal 228 ayat 7). Bipartit tidak perlu jika pekerja mengundurkan diri, PKWT berakhir, pensiun sesuai perjanjian, atau meninggal dunia (Pasal 229). PHK dilarang dengan alasan: sakit lebih dari 12 bulan berturut-turut yang belum pasti sembuh; menjalankan kewajiban negara; ibadah; menikah; hamil, melahirkan, gugur kandungan, atau menyusui; hubungan keluarga dengan pekerja lain di perusahaan yang sama; berserikat; melapor tindak pidana; beda paham, agama, aliran politik, suku, ras, golongan, jenis kelamin, kondisi fisik, atau status perkawinan; serta disabilitas tetap atau sakit akibat kerja. PHK dengan alasan ini batal demi hukum (Pasal 230).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (14,'Alasan PHK yang sah dan pengunduran diri','alasan phk sah mangkir surat peringatan sp1 sp2 sp3 ditahan pensiun mengundurkan diri resign','Alasan PHK yang sah antara lain: penggabungan, peleburan, atau pengambilalihan; perusahaan tutup karena rugi terus-menerus 2 tahun; tutup permanen oleh pemilik; keadaan memaksa; PKPU; pailit; permohonan PHK pekerja karena perbuatan pemberi kerja; putusan PHI; pengunduran diri; mangkir 5 hari kerja berturut-turut setelah dipanggil 2 kali; pelanggaran dengan SP1-SP3 yang masing-masing berlaku 6 bulan; ditahan 6 bulan; sakit berkepanjangan atau disabilitas akibat kerja melampaui 12 bulan; pensiun; meninggal dunia (Pasal 231). Pengunduran diri wajib tertulis paling lambat 30 hari sebelum tanggal mulai, tanpa terikat ikatan dinas, dan pekerja tetap bekerja sampai tanggal itu (Pasal 231 huruf i). Selama proses PHI, pemberi kerja dapat melakukan skors dengan tetap membayar upah dan hak lain (Pasal 235).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (15,'Disiplin dan surat peringatan','disiplin sanksi surat peringatan sp teguran skorsing pelanggaran peraturan perusahaan','Sanksi disiplin dan surat peringatan wajib diatur dalam peraturan perusahaan atau PKB (Pasal 179 ayat 1 huruf b dan c). SP1 sampai SP3 yang masing-masing berlaku 6 bulan dapat menjadi alasan PHK jika pelanggaran berulang (Pasal 231 huruf k; Pasal 244). Surat peringatan harus dilakukan secara tertulis dan memuat jenis pelanggaran serta batas waktu berlakunya. Sebelum PHK karena pelanggaran, bipartit wajib dilakukan (Pasal 228). Tata cara penjatuhan sanksi detail diatur dalam peraturan perusahaan.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (16,'Menahan ijazah dan dokumen pribadi','ijazah dokumen pribadi jaminan tahan ijazah bpjs kartu identitas','Dilarang mensyaratkan atau menahan ijazah dan dokumen pribadi pekerja sebagai jaminan (Pasal 78 ayat 1). Pengecualian: dokumen dari pendidikan dan pelatihan yang dibiayai pemberi kerja berdasarkan perjanjian tertulis (Pasal 78 ayat 2). Pelanggaran dikenai sanksi administratif, termasuk peringatan tertulis, denda administratif, pembatasan kegiatan usaha, dan kewajiban mengembalikan dokumen (Pasal 79).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (17,'Serikat pekerja','serikat pekerja buruh berserikat anggota union pengurus intimidasi','Setiap pekerja berhak membentuk dan menjadi anggota serikat pekerja. Pengurus tetap menjalankan kewajiban kerjanya. Serikat berhak mengelola keuangan, termasuk dana mogok (Pasal 168). Dilarang menghalangi atau memaksa pekerja untuk berserikat, misalnya dengan PHK, skors, mutasi, penurunan jabatan, tidak membayar upah, intimidasi, atau kampanye anti serikat. Pelanggaran adalah tindak pidana (Pasal 169 dan Pasal 291). Serikat tidak tercatat tetap dapat berserikat, tetapi perundingan PKB hanya dengan serikat yang tercatat (Pasal 187-191).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (18,'Bipartit, peraturan perusahaan (PP), dan PKB','bipartit lks peraturan perusahaan pp pkb perjanjian kerja bersama kesepakatan perundingan','Perusahaan dengan 10 pekerja atau lebih wajib membentuk LKS Bipartit; usaha mikro dan kecil boleh (Pasal 171; sanksi administratif Pasal 172). Perusahaan dengan 10 pekerja atau lebih wajib membuat peraturan perusahaan (PP), kecuali sudah ada PKB (Pasal 175-176). PP wajib meminta pendapat perwakilan pekerja; jika ada serikat, perwakilannya pengurus serikat (Pasal 178). Isi PP minimal: hak dan kewajiban pengusaha, hak dan kewajiban pekerja, syarat kerja, tata tertib, dan masa berlaku (Pasal 179 ayat 1). Masa berlaku PP paling lama 2 tahun dan wajib diperbarui (Pasal 179 ayat 3). Pengesahan PP paling lama 30 hari kerja; jika lewat, PP dianggap sah (Pasal 181). Pengusaha wajib menjelaskan dan membagikan salinan PP kepada pekerja (Pasal 183-184). PKB dibuat dengan serikat tercatat; satu perusahaan hanya boleh memiliki satu PKB (Pasal 187-189). Jika hanya ada satu serikat, serikat itu dapat mewakili perundingan bila anggotanya lebih dari 30%; jika tidak, perlu dukungan lebih dari 50% melalui pemungutan suara (Pasal 190). Masa berlaku PKB paling lama 2 tahun, dapat diperpanjang paling lama 1 tahun; perundingan PKB berikutnya dimulai paling lambat 3 bulan sebelum berakhir (Pasal 194). Perjanjian kerja yang bertentangan dengan PKB batal demi hukum (Pasal 200). Pengusaha dilarang mengganti PKB dengan PP selama serikat masih ada (Pasal 202).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (19,'Mogok kerja','mogok kerja demo unjuk rasa pekerja mogok sah tidak sah pengganti','Mogok kerja adalah hak dasar yang dilakukan secara sah, tertib, dan damai setelah perundingan gagal: pengusaha tidak mau berunding, atau tidak tercapai kesepakatan setelah 3 kali perundingan atau 30 hari kerja (Pasal 211). Ajakan mogok tidak boleh melanggar hukum; pekerja boleh memilih ikut atau tidak (Pasal 212). Pemberitahuan tertulis paling lambat 7 hari kerja sebelumnya kepada pengusaha dan pemerintah daerah, memuat waktu, tempat, alasan, dan tanda tangan penanggung jawab (Pasal 214). Mogok yang tidak memenuhi syarat ini adalah mogok tidak sah (Pasal 216). Dilarang menghalangi mogok sah, dan dilarang menangkap atau menahan pekerja dan pengurus serikat yang mogok sah (Pasal 217). Selama dan sesudah mogok sah, pengusaha dilarang mengganti pekerja mogok dengan pekerja dari luar, atau memberi sanksi balasan (Pasal 218; sanksi Pasal 219). Pekerja yang mogok sah untuk menuntut hak normatif yang dilanggar tetap berhak atas upah (Pasal 220).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (20,'Penutupan perusahaan (lockout)','penutupan perusahaan tutup pabrik lockout layanan publik rumah sakit','Penutupan perusahaan adalah hak dasar pengusaha, tetapi tidak boleh sebagai balasan atas tuntutan normatif. Dilarang untuk layanan umum dan objek vital, misalnya rumah sakit, air bersih, telekomunikasi, listrik, kereta api, dan migas (Pasal 221-222). Pemberitahuan tertulis paling lambat 7 hari kerja sebelum penutupan (Pasal 223). Selama proses penutupan, upah tetap dibayar (Pasal 225). Penutupan yang tidak memenuhi syarat adalah penutupan tidak sah (Pasal 226).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (21,'Penyelesaian perselisihan hubungan industrial','perselisihan hubungan industrial phi bipartit mediasi konsiliasi arbitrase pengadilan hubungan industrial gugatan','Perselisihan hubungan industrial wajib diupayakan melalui musyawarah. Jika gagal, lewat prosedur PHI sesuai UU 2/2004 tentang Penyelesaian Perselisihan Hubungan Industrial, yang tetap berlaku (Pasal 210). Dalam PHK, bipartit paling lama 30 hari kerja, lalu PHI (Pasal 228 ayat 4-5). Perkara PHI yang sudah didaftarkan sebelum UU 27/2026 berlaku diselesaikan dengan UU lama (Pasal 300). Untuk kasus yang sudah masuk mediasi, konsiliasi, arbitrase, atau PHI, konsultasikan dengan advokat atau konsultan HI.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (22,'K3 (keselamatan kerja) dan kesehatan','k3 keselamatan kerja kecelakaan kerja smk3 apd pemeriksaan kesehatan komite','Pemberi kerja wajib menerapkan K3 untuk mencegah kecelakaan dan penyakit akibat kerja (Pasal 128). SMK3 wajib untuk perusahaan dengan minimal 100 pekerja atau tingkat risiko tinggi (Pasal 130 ayat 3). Pemeriksaan kesehatan pekerja minimal 1 kali setahun, APD atas biaya perusahaan, dan pelaporan kecelakaan kerja (Pasal 130 ayat 6). Perusahaan wajib membentuk komite K3 yang terdiri atas unsur pengusaha dan pekerja (Pasal 131). Kelalaian K3 yang berakibat disabilitas total tetap atau kematian diancam pidana penjara 6 tahun (Pasal 286).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (23,'Perempuan, anak, dan disabilitas','perempuan hamil anak disabilitas difabel pelecehan seksual diskriminasi kesempatan kerja laktasi malam','Dilarang membatasi atau membedakan perlakuan karena status perkawinan, kehamilan, persalinan, keguguran, atau menyusui. Pekerja hamil dilarang bekerja pada pekerjaan berisiko tinggi dan malam hari pukul 23.00 sampai 07.00. Pemberi kerja wajib memberi kesempatan karier yang sama, menyediakan ruang dan fasilitas laktasi, dan menetapkan kebijakan tanpa toleransi pelecehan dan kekerasan seksual (Pasal 114). Dilarang mempekerjakan anak di bawah 18 tahun, dengan pengecualian pekerjaan ringan (Pasal 106-107). Pemberi kerja wajib melindungi pekerja penyandang disabilitas dan mempekerjakan minimal 1% dari jumlah pekerja; pemerintah dan BUMN/BUMD minimal 2% (Pasal 104-105).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (24,'Jaminan sosial','bpjs jaminan sosial jkn jkk jkm jht jp jkp jaminan kehilangan pekerjaan','Pemberi kerja wajib mengikutsertakan pekerja dalam jaminan sosial: JKN, JKK, JKM, JHT, JP, dan JKP (Pasal 155 ayat 2-3). Tidak mengikutsertakan pekerja dapat dipidana, hanya jika sanksi administratif tidak dipatuhi, dan tidak berlaku untuk UMK (Pasal 290). Selama masa percobaan PKWTT, jaminan sosial wajib (Pasal 92 ayat 2).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (25,'Pekerja platform dan kemitraan','platform digital kemitraan ojol ojek online driver kurir mitra','Hubungan kerja tertentu, termasuk kemitraan dan platform digital, berhak atas penghasilan layak, K3, dan jaminan sosial, serta diatur dengan ketentuan tersendiri (Pasal 102-103). Pekerja tertentu yang bermitra juga berhak atas pesangon sesuai kesepakatan (Pasal 251).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (26,'Sanksi pidana dan administratif','sanksi pidana denda penjara administratif hukuman pelanggaran pengusaha tindak pidana','Sanksi administratif umum: peringatan tertulis, denda administratif, pembatasan kegiatan usaha, penghentian sementara kegiatan usaha, dan pencabutan perizinan berusaha (Pasal 79; Pasal 117; Pasal 253 ayat 6-7). Contoh pidana: upah di bawah UMP (Pasal 288); upah lembur tidak dibayar (Pasal 285); menghalangi serikat (Pasal 291); menghalangi mogok sah (Pasal 292); kelalaian K3 yang menyebabkan kematian atau disabilitas total tetap (Pasal 286); tidak mengikutsertakan jaminan sosial setelah sanksi administratif diabaikan (Pasal 290). Ancaman dan besaran pidana mengikuti pasal masing-masing. Verifikasi ancaman pidana ke naskah resmi sebelum dikutip dalam dokumen formal.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (27,'Pengawasan ketenagakerjaan','pengawas ketenagakerjaan inspeksi pemeriksaan pengawasan penyidik laporan','Pengawas ketenagakerjaan berwenang memasuki tempat kerja, memanggil pihak, memberi perintah perbaikan, dan mengambil tindakan yang diperlukan (Pasal 257-262). Pemberi kerja wajib memberi akses dan data kepada pengawas (Pasal 259) dan melaporkan kondisi ketenagakerjaan serta menindaklanjuti rekomendasi (Pasal 264). Pengawas ketenagakerjaan berwenang sebagai penyidik pegawai negeri sipil (Pasal 267).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (28,'Status hukum dan masa transisi','berlaku dicabut uu 13 2003 cipta kerja pp 35 2021 pp 36 2021 peraturan pelaksana transisi','UU 27/2026 mulai berlaku sejak diundangkan, 28 Oktober 2026 (Pasal 313). UU 13/2003 tentang Ketenagakerjaan dicabut; Pasal 80 huruf a dan Pasal 81 dalam Lampiran UU 6/2023 dicabut (Pasal 311). Peraturan pelaksana UU 13/2003 dan UU 6/2023, termasuk PP 35/2021 dan PP 36/2021, tetap berlaku sepanjang tidak bertentangan dengan UU 27/2026 (Pasal 310). Peraturan pelaksana UU 27/2026 wajib ditetapkan paling lama 1 tahun sejak diundangkan (Pasal 312). Penyesuaian alih daya paling lama 1 tahun (Pasal 306). Undang-undang lain yang tidak disebut dicabut tetap berlaku, termasuk UU 2/2004 dan UU 21/2000.','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
INSERT INTO regulasi (id,topik,kata_kunci,teks,sumber,status) VALUES (29,'Dana dan ketentuan pekerja meninggal','meninggal dunia ahli waris kematian pekerja meninggal','Jika pekerja meninggal dunia, ahli waris menerima pesangon 2x, UPMK 1x, dan UPH (Pasal 249). PHK tidak diperlukan bipartit dalam kasus meninggal dunia (Pasal 229).','UU 27/2026 (indeks pasal, diverifikasi)','berlaku');
